arguments.command:
# Let's use a more targeted approach - write a small C# script to read the binlog programmatically
dotnet new console -o /tmp/binlog-reader --force -q 2>/dev/null
cd /tmp/binlog-reader
dotnet add package MSBuild.StructuredLogger --version 2.2.* -q 2>/dev/null

cat > Program.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild(args[0]);
var errors = new List<(string Project, string File, int Line, string Code, string Message)>();
var warnings = new List<(string Project, string File, int Line, string Code, string Message)>();

// Collect all errors and warnings
build.VisitAllChildren<Error>(e => {
    var proj = e.GetNearestParent<Project>()?.Name ?? "unknown";
    errors.Add((proj, e.File ?? "", e.LineNumber, e.Code ?? "", e.Message ?? ""));
});

build.VisitAllChildren<Warning>(w => {
    var proj = w.GetNearestParent<Project>()?.Name ?? "unknown";
    warnings.Add((proj, w.File ?? "", w.LineNumber, w.Code ?? "", w.Message ?? ""));
});

// Get project dependency graph
Console.WriteLine("=== PROJECT STRUCTURE ===");
build.VisitAllChildren<Project>(p => {
    Console.WriteLine($"Project: {p.Name} (Target: {p.TargetFramework})");
});

// Look for all items of type PackageReference
Console.WriteLine("\n=== PACKAGE REFERENCES (from Items) ===");
build.VisitAllChildren<Folder>(f => {
    if (f.Name == "PackageReference") {
        var proj = f.GetNearestParent<Project>()?.Name ?? "unknown";
        foreach (var child in f.Children) {
            Console.WriteLine($"  [{proj}] {child}");
        }
    }
});

Console.WriteLine("\n=== PROJECT REFERENCES ===");
build.VisitAllChildren<Folder>(f => {
    if (f.Name == "ProjectReference") {
        var proj = f.GetNearestParent<Project>()?.Name ?? "unknown";
        foreach (var child in f.Children) {
            Console.WriteLine($"  [{proj}] {child}");
        }
    }
});

Console.WriteLine("\n=== ERRORS ===");
foreach (var e in errors) {
    Console.WriteLine($"  [{e.Project}] {e.Code}: {e.Message}");
    Console.WriteLine($"    at {e.File}:{e.Line}");
}

Console.WriteLine("\n=== WARNINGS ===");
foreach (var w in warnings) {
    Console.WriteLine($"  [{w.Project}] {w.Code}: {w.Message}");
}

// Check for failed projects
Console.WriteLine("\n=== BUILD RESULTS ===");
build.VisitAllChildren<Project>(p => {
    Console.WriteLine($"  {p.Name}: Succeeded={p.Succeeded}");
});
EOF

